PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "sorteos_sorteo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL UNIQUE, "activo" bool NOT NULL, "horarios" text NOT NULL CHECK ((JSON_VALID("horarios") OR "horarios" IS NULL)), "hora_salida" time NULL, "minutos_cierre" integer NOT NULL, "creado_en" datetime NOT NULL, "actualizado_en" datetime NOT NULL, "origen" varchar(20) NOT NULL, "formas_juego" text NOT NULL CHECK ((JSON_VALID("formas_juego") OR "formas_juego" IS NULL)));
COMMIT;
